states=read('results/STATE_AUDIT.json')
complete=a['complete_harness'];table=[]
for seed in [202610205301,202610205302]:
 for arm in ['R-W','A-W','R-N_OLD','R-SH_OLD']:
  def metric(phase,cohort):
   c=next((c for c in curves if c['seed']==seed and c['arm']==arm and c['phase']==phase and c['cohort']==cohort),None)
   return f"{100*c['exact']:.1f}%" if c else 'not reached'
  n=sum(r['seed']==seed and r['arm']==arm for r in train)
  table.append(f"| {seed} | {arm} | {n} | {metric('OLD512','OLD')} | {metric('FINAL','OLD')} | {metric('FINAL','NEW')} | {metric('FINAL','HELD')} |")
