   rs=[r for r in train if r['seed']==seed and r['arm']==arm and r['phase']==phase]
   if not rs:continue
   z=rs[-16:];last.append(f"| {seed} | {arm} | {phase} | {len(rs)} | {sum(r['loss'] for r in z)/len(z):.4f} | {sum(r['correct_teacher_prefix'] for r in z)/sum(r['target_events'] for r in z):.1%} | {sum(r['bit_correct'] for r in z)/sum(r['bit_count'] for r in z):.1%} |")
